def _kind(unit: str) -> str:
    return {"g": "g", "ml": "ml", "개": "ea"}.get(unit, "g")


def all_presets() -> list[dict]:
    """번호(id)를 붙인 기본 레시피 목록."""
    out = []
    for i, (name, cat, aliases, lines, note) in enumerate(PRESETS, start=1):
        out.append({"id": i, "name": name, "category": cat, "aliases": list(aliases), "serving_note": note,
                    "lines": [{"name": n, "qty": float(q), "unit": u, "kind": _kind(u)} for n, q, u in lines]})
    return out


def get(pid: int) -> dict | None:
    if 1 <= pid <= len(PRESETS):
        return all_presets()[pid - 1]
    return None
